import React, { useEffect, useState } from 'react'
import useApi from '../../../../hooks/useApi'
import hospitalsApi from '../../../../api/hospitals/hospitalsApi'
import { Collapse } from 'antd'

export default function AdmissionLaboratoryOrders({selectedAdmission}) {

    const [admissionlaboratoryOrders, setadmissionlaboratoryOrders] = useState([])
    
      const [data, setData] = useState([])
    
      const getAdmissionLaboratoryOrdersApi = useApi(hospitalsApi.hospitalStaffAction)
      const getAdmissionLaboratoryOrders = async (id) => {
        await getAdmissionLaboratoryOrdersApi.request({
          "action": "GetAdmissionLaboratoryOrders",
          "admission": id
        })
      }
      useEffect(() => {
        if (selectedAdmission) {
    
          getAdmissionLaboratoryOrders(selectedAdmission.id)
        }
    
      }, [selectedAdmission])
      useEffect(() => {
        if (getAdmissionLaboratoryOrdersApi.data) {
          if (getAdmissionLaboratoryOrdersApi.data.length) {
            setadmissionlaboratoryOrders(getAdmissionLaboratoryOrdersApi.data)
          }
        }
    
        console.log("getAdmissionLaboratoryOrdersApi.data", getAdmissionLaboratoryOrdersApi.data)
      }, [getAdmissionLaboratoryOrdersApi.data])
    
    
      useEffect(() => {
        if (admissionlaboratoryOrders) {
          if (admissionlaboratoryOrders.length) {
            setData(admissionlaboratoryOrders.map((i, index) => ({
              label: `${i.reference_number} - ${i.created}  ${i.destination_department_title}`,
              key: index+1,
              children: <div>
                {
                  i.examinations && i.examinations.length ? <div>
    
                    {
                      i.examinations.map((y,yIn) => {
                        return <div>
                          <p className=''>
                          <span className='mx-2'>{yIn+1}.</span>
                          <span className='mx-2'>{y.examination_name}</span>
                          <span className='mx-2 font-semibold'>KES {parseFloat(y.examination_charge).toFixed(2).toString()}</span>
                          </p>
    
                        </div>
                      })
                    }
                  </div> : <div></div>
                }
              </div>
            })))
          }
        }
    
        console.log("getDependantLaboratoryOrdersApi.data", getAdmissionLaboratoryOrdersApi.data)
      }, [admissionlaboratoryOrders])
  return (
    <div>
    <p className='text-2xl font-semibold text-center'>Admission Laboratory Orders</p>
    {admissionlaboratoryOrders && admissionlaboratoryOrders.length ? <Collapse items={data} defaultActiveKey={['1']} /> : <>
      <p className='text-center'>No items retrieved</p>
      </>}
    </div>
  )
}
